/bin/bash -lc "node <<'NODE'
const assert = require('node:assert/strict');
const { retry_delay } = require('./logic');
let checks = 0;
for (let attempt = 0; attempt <= 60; attempt++) {
  for (const base of [0, 1, 2, 3, 10, 1000, Number.MAX_SAFE_INTEGER, Number.MAX_VALUE]) {
    for (const cap of [0, 1, 2, 3, 100, 1000, Number.MAX_SAFE_INTEGER, Number.MAX_VALUE]) {
      const exact = BigInt(base) * (2n ** BigInt(attempt));
      const expected = exact >= BigInt(cap) ? cap : Number(exact);
      const actual = retry_delay(attempt, base, cap);
      assert.equal(actual, expected, JSON.stringify({ attempt, base, cap }));
      assert.ok(Number.isFinite(actual) && Number.isInteger(actual) && actual >= 0);
      checks++;
    }
  }
}
console.log("'`${checks} boundary checks passed for attempts 0 through 60.`);
NODE'

